func (ws *WebSocketClient) SubscribeToOrderBook(pairs []string, depth int) error {
	log.Println(pairs)
	sub, err := json.Marshal(&types.SubscribeV2{
		Method: "subscribe",
		Params: types.ParamsV2{
			Depth:   depth,
			Channel: "book",
			Symbol:  pairs,
		},
	})
	if err != nil {
		//log.Println("error marshaling: ", err)
